-- Equalizer schema v11: adds 15 original circuit-logic questions to the
-- ACL (AOS/AET) bank, tagged Logic/Reasoning, plus an optional diagram_svg
-- column so questions can carry a hand-drawn schematic (inline SVG, shown
-- above the question text) instead of describing a circuit purely in words.
-- Each of the 15 questions below ships with its own diagram. Written from
-- scratch, not copied from any source.

alter table public.questions
  add column if not exists diagram_svg text;

insert into public.questions (subject, category, question, options, answer_index, explanation, diagram_svg) values

('acl', 'Logic/Reasoning', 'A circuit has a battery connected to a light bulb through two switches, Switch X and Switch Y, wired one after another along the same single path (in series) -- meaning current must pass through both switches to complete the loop. Which of the following actions will make the light glow?',
 '["Open both Switch X and Switch Y", "Close Switch X and open Switch Y", "Open Switch X and close Switch Y", "Close both Switch X and Switch Y", "All of the above except the first option", "None of the above"]'::jsonb,
 3, 'In a series circuit, current has only one path, so every switch along that path must be closed for current to flow. With Switch X or Switch Y open, the loop is broken. Only closing both completes the circuit.',
 '<svg viewBox="0 0 300 145" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="96" y2="30"/><circle cx="96" cy="30" r="2.5" fill="currentColor"/><line x1="96" y1="30" x2="121" y2="19"/><circle cx="124" cy="30" r="2.5" fill="currentColor"/><text x="110" y="18" font-size="10.5" text-anchor="middle">Switch X</text><line x1="124" y1="30" x2="176" y2="30"/><circle cx="176" cy="30" r="2.5" fill="currentColor"/><line x1="176" y1="30" x2="201" y2="19"/><circle cx="204" cy="30" r="2.5" fill="currentColor"/><text x="190" y="18" font-size="10.5" text-anchor="middle">Switch Y</text><line x1="204" y1="30" x2="270" y2="30"/><line x1="30" y1="110" x2="270" y2="110"/><line x1="270" y1="30" x2="270" y2="56"/><circle cx="270" cy="70" r="14"/><line x1="261" y1="61" x2="279" y2="79"/><line x1="279" y1="61" x2="261" y2="79"/><line x1="270" y1="84" x2="270" y2="110"/><text x="270" y="126" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A battery is connected to a light bulb. Two switches, Switch M and Switch N, are wired as two separate parallel branches between the battery and the bulb -- current can complete the circuit by passing through either switch independently. Which of the following actions will make the light glow?',
 '["Open both Switch M and Switch N", "Close Switch M and open Switch N", "Open Switch M and close Switch N", "Close both Switch M and Switch N", "All of the above except the first option", "None of the above"]'::jsonb,
 4, 'In a parallel circuit, each branch offers its own complete path to the battery. Closing either switch alone -- or both -- completes at least one path, so the light glows in every case except when both are open.',
 '<svg viewBox="0 0 300 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="60"/><line x1="90" y1="25" x2="90" y2="120"/><line x1="90" y1="60" x2="136" y2="60"/><circle cx="136" cy="60" r="2.5" fill="currentColor"/><line x1="136" y1="60" x2="161" y2="49"/><circle cx="164" cy="60" r="2.5" fill="currentColor"/><text x="150" y="48" font-size="10.5" text-anchor="middle">Switch M</text><line x1="164" y1="60" x2="210" y2="60"/><line x1="90" y1="120" x2="136" y2="120"/><circle cx="136" cy="120" r="2.5" fill="currentColor"/><line x1="136" y1="120" x2="161" y2="109"/><circle cx="164" cy="120" r="2.5" fill="currentColor"/><text x="150" y="140" font-size="10.5" text-anchor="middle">Switch N</text><line x1="164" y1="120" x2="210" y2="120"/><line x1="210" y1="60" x2="210" y2="25"/><line x1="210" y1="120" x2="210" y2="25"/><line x1="210" y1="25" x2="270" y2="25"/><line x1="30" y1="155" x2="270" y2="155"/><line x1="270" y1="25" x2="270" y2="76"/><circle cx="270" cy="90" r="14"/><line x1="261" y1="81" x2="279" y2="99"/><line x1="279" y1="81" x2="261" y2="99"/><line x1="270" y1="104" x2="270" y2="155"/><text x="270" y="171" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A circuit connects a battery to a light bulb through three switches -- Switch 1, Switch 2, and Switch 3 -- all wired in series along a single path. Which combination of switch positions will make the light glow?',
 '["Switch 1 closed, Switch 2 open, Switch 3 closed", "Switch 1 closed, Switch 2 closed, Switch 3 open", "All three switches open", "All three switches closed", "Any two of the three switches closed", "None of the above"]'::jsonb,
 3, 'A series path is only complete when every component along it is closed. If even one of the three switches is open, the single available path is broken and the light cannot glow.',
 '<svg viewBox="0 0 350 145" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="86" y2="30"/><circle cx="86" cy="30" r="2.5" fill="currentColor"/><line x1="86" y1="30" x2="111" y2="19"/><circle cx="114" cy="30" r="2.5" fill="currentColor"/><text x="100" y="18" font-size="10.5" text-anchor="middle">Switch 1</text><line x1="114" y1="30" x2="161" y2="30"/><circle cx="161" cy="30" r="2.5" fill="currentColor"/><line x1="161" y1="30" x2="186" y2="19"/><circle cx="189" cy="30" r="2.5" fill="currentColor"/><text x="175" y="18" font-size="10.5" text-anchor="middle">Switch 2</text><line x1="189" y1="30" x2="236" y2="30"/><circle cx="236" cy="30" r="2.5" fill="currentColor"/><line x1="236" y1="30" x2="261" y2="19"/><circle cx="264" cy="30" r="2.5" fill="currentColor"/><text x="250" y="18" font-size="10.5" text-anchor="middle">Switch 3</text><line x1="264" y1="30" x2="320" y2="30"/><line x1="30" y1="110" x2="320" y2="110"/><line x1="320" y1="30" x2="320" y2="56"/><circle cx="320" cy="70" r="14"/><line x1="311" y1="61" x2="329" y2="79"/><line x1="329" y1="61" x2="311" y2="79"/><line x1="320" y1="84" x2="320" y2="110"/><text x="320" y="126" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'In a circuit, Switch C is wired in series between the battery and a junction. From that junction, two parallel branches -- one through Switch A, one through Switch B -- reconnect before reaching the light bulb. Which of the following will make the light glow?',
 '["Switch C open, Switch A closed, Switch B closed", "Switch C closed, Switch A open, Switch B open", "Switch C closed, Switch A closed, Switch B open", "Switch C open, Switch A open, Switch B open", "Exactly one of Switch A or Switch B closed, with Switch C open", "None of the above"]'::jsonb,
 2, 'Because Switch C sits in series before the parallel pair, current cannot reach either branch unless C is closed. Once C is closed, the light glows as long as at least one of Switch A or Switch B is also closed.',
 '<svg viewBox="0 0 360 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="81" y2="25"/><circle cx="81" cy="25" r="2.5" fill="currentColor"/><line x1="81" y1="25" x2="106" y2="14"/><circle cx="109" cy="25" r="2.5" fill="currentColor"/><text x="95" y="13" font-size="10.5" text-anchor="middle">Switch C</text><line x1="109" y1="25" x2="150" y2="25"/><line x1="150" y1="25" x2="150" y2="60"/><line x1="150" y1="25" x2="150" y2="120"/><line x1="150" y1="60" x2="196" y2="60"/><circle cx="196" cy="60" r="2.5" fill="currentColor"/><line x1="196" y1="60" x2="221" y2="49"/><circle cx="224" cy="60" r="2.5" fill="currentColor"/><text x="210" y="48" font-size="10.5" text-anchor="middle">Switch A</text><line x1="224" y1="60" x2="270" y2="60"/><line x1="150" y1="120" x2="196" y2="120"/><circle cx="196" cy="120" r="2.5" fill="currentColor"/><line x1="196" y1="120" x2="221" y2="109"/><circle cx="224" cy="120" r="2.5" fill="currentColor"/><text x="210" y="140" font-size="10.5" text-anchor="middle">Switch B</text><line x1="224" y1="120" x2="270" y2="120"/><line x1="270" y1="60" x2="270" y2="25"/><line x1="270" y1="120" x2="270" y2="25"/><line x1="270" y1="25" x2="330" y2="25"/><line x1="30" y1="155" x2="330" y2="155"/><line x1="330" y1="25" x2="330" y2="76"/><circle cx="330" cy="90" r="14"/><line x1="321" y1="81" x2="339" y2="99"/><line x1="339" y1="81" x2="321" y2="99"/><line x1="330" y1="104" x2="330" y2="155"/><text x="330" y="171" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'Two identical light bulbs, Bulb A and Bulb B, are connected in series with a battery and a single switch -- meaning all three components share the same single loop. The switch is closed and both bulbs are glowing. If Bulb A suddenly burns out, breaking that part of the circuit, what happens to Bulb B?',
 '["Bulb B glows brighter than before", "Bulb B continues to glow at the same brightness", "Bulb B goes out completely", "Bulb B glows more dimly but stays on", "Bulb B is unaffected because it has its own separate path", "The switch must be opened for Bulb B to be affected"]'::jsonb,
 2, 'In a series circuit, all components share one continuous loop. A break at Bulb A interrupts the only path current can take, so Bulb B loses its current too and goes out, even though nothing is wrong with Bulb B itself.',
 '<svg viewBox="0 0 300 145" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="76" y2="30"/><circle cx="76" cy="30" r="2.5" fill="currentColor"/><line x1="76" y1="30" x2="101" y2="19"/><circle cx="104" cy="30" r="2.5" fill="currentColor"/><text x="90" y="18" font-size="10.5" text-anchor="middle">Switch</text><line x1="104" y1="30" x2="156" y2="30"/><circle cx="170" cy="30" r="14"/><line x1="161" y1="21" x2="179" y2="39"/><line x1="179" y1="21" x2="161" y2="39"/><text x="170" y="10" font-size="10.5" text-anchor="middle">Bulb A</text><line x1="184" y1="30" x2="216" y2="30"/><circle cx="230" cy="30" r="14"/><line x1="221" y1="21" x2="239" y2="39"/><line x1="239" y1="21" x2="221" y2="39"/><text x="230" y="10" font-size="10.5" text-anchor="middle">Bulb B</text><line x1="244" y1="30" x2="270" y2="30"/><line x1="270" y1="30" x2="270" y2="110"/><line x1="30" y1="110" x2="270" y2="110"/><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'Two identical light bulbs, Bulb A and Bulb B, are each connected directly to the same battery through their own separate wires (in parallel), with no shared switch. Both bulbs are currently glowing. If Bulb A burns out, what happens to Bulb B?',
 '["Bulb B goes out completely, since the circuit is broken", "Bulb B also burns out shortly after", "Bulb B continues to glow normally, since its path to the battery is independent", "Bulb B begins to flicker", "Bulb B glows more dimly", "Both bulbs must be replaced together"]'::jsonb,
 2, 'In a parallel circuit, each bulb has its own independent path back to the battery. Losing Bulb A only breaks its own branch -- Bulb B''s branch is untouched, so it keeps glowing normally.',
 '<svg viewBox="0 0 300 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="60"/><line x1="90" y1="25" x2="90" y2="120"/><line x1="90" y1="60" x2="166" y2="60"/><circle cx="180" cy="60" r="14"/><line x1="171" y1="51" x2="189" y2="69"/><line x1="189" y1="51" x2="171" y2="69"/><text x="180" y="40" font-size="10.5" text-anchor="middle">Bulb A</text><line x1="194" y1="60" x2="270" y2="60"/><line x1="90" y1="120" x2="166" y2="120"/><circle cx="180" cy="120" r="14"/><line x1="171" y1="111" x2="189" y2="129"/><line x1="189" y1="111" x2="171" y2="129"/><text x="180" y="148" font-size="10.5" text-anchor="middle">Bulb B</text><line x1="194" y1="120" x2="270" y2="120"/><line x1="270" y1="60" x2="270" y2="25"/><line x1="270" y1="120" x2="270" y2="25"/><line x1="270" y1="25" x2="270" y2="155"/><line x1="30" y1="155" x2="270" y2="155"/><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A circuit has a battery and a light bulb connected by a single wire, forming a complete loop. A student cuts this wire, breaking the circuit permanently at that point (the original wire cannot be reconnected). A new Switch P is added, wired to create a second, separate path around the cut section. Which action will make the light glow?',
 '["Leaving Switch P open", "Closing Switch P", "The light cannot glow again since the original wire is cut", "Closing Switch P will only make the light flicker", "Switch P must be opened and closed repeatedly to light it", "None of the above"]'::jsonb,
 1, 'Even though the original path is permanently broken, Switch P provides an entirely separate route between the same two points. Closing it completes that alternate path, so current can flow and the light glows again.',
 '<svg viewBox="0 0 300 175" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="270" y2="30"/><line x1="270" y1="30" x2="270" y2="56"/><circle cx="270" cy="70" r="14"/><line x1="261" y1="61" x2="279" y2="79"/><line x1="279" y1="61" x2="261" y2="79"/><line x1="270" y1="84" x2="270" y2="110"/><text x="270" y="126" font-size="11" text-anchor="middle">Bulb</text><line x1="270" y1="110" x2="150" y2="110"/><line x1="144" y1="102" x2="152" y2="118"/><line x1="108" y1="102" x2="116" y2="118"/><line x1="30" y1="110" x2="110" y2="110"/><text x="130" y="96" font-size="10" text-anchor="middle">(cut)</text><line x1="150" y1="110" x2="150" y2="145"/><line x1="150" y1="145" x2="144" y2="145"/><circle cx="116" cy="145" r="2.5" fill="currentColor"/><line x1="116" y1="145" x2="141" y2="134"/><circle cx="144" cy="145" r="2.5" fill="currentColor"/><text x="130" y="165" font-size="10.5" text-anchor="middle">Switch P</text><line x1="110" y1="145" x2="116" y2="145"/><line x1="110" y1="145" x2="110" y2="110"/><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'In a circuit, Switch 1 and Switch 2 are wired in series to form one branch between the battery and the light bulb. This branch is wired in parallel with a second, separate branch containing only Switch 3. Which of the following will make the light glow?',
 '["Switch 1 open, Switch 2 open, Switch 3 open", "Switch 1 closed, Switch 2 open, Switch 3 open", "Switch 1 open, Switch 2 closed, Switch 3 open", "Switch 1 closed, Switch 2 closed, Switch 3 open", "Switch 1 open, Switch 2 open, Switch 3 closed", "Both the fourth and fifth options above will make the light glow"]'::jsonb,
 5, 'The light glows if either branch is complete. The first branch needs both Switch 1 and Switch 2 closed; the second branch just needs Switch 3 closed. Closing Switch 1 and 2 together works, and closing Switch 3 alone also works -- either satisfies the parallel connection.',
 '<svg viewBox="0 0 360 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="55"/><line x1="90" y1="25" x2="90" y2="125"/><line x1="90" y1="55" x2="141" y2="55"/><circle cx="141" cy="55" r="2.5" fill="currentColor"/><line x1="141" y1="55" x2="166" y2="44"/><circle cx="169" cy="55" r="2.5" fill="currentColor"/><text x="155" y="43" font-size="10.5" text-anchor="middle">Switch 1</text><line x1="169" y1="55" x2="201" y2="55"/><circle cx="201" cy="55" r="2.5" fill="currentColor"/><line x1="201" y1="55" x2="226" y2="44"/><circle cx="229" cy="55" r="2.5" fill="currentColor"/><text x="215" y="43" font-size="10.5" text-anchor="middle">Switch 2</text><line x1="229" y1="55" x2="270" y2="55"/><line x1="90" y1="125" x2="166" y2="125"/><circle cx="166" cy="125" r="2.5" fill="currentColor"/><line x1="166" y1="125" x2="191" y2="114"/><circle cx="194" cy="125" r="2.5" fill="currentColor"/><text x="180" y="145" font-size="10.5" text-anchor="middle">Switch 3</text><line x1="194" y1="125" x2="270" y2="125"/><line x1="270" y1="55" x2="270" y2="25"/><line x1="270" y1="125" x2="270" y2="25"/><line x1="270" y1="25" x2="330" y2="25"/><line x1="30" y1="155" x2="330" y2="155"/><line x1="330" y1="25" x2="330" y2="76"/><circle cx="330" cy="90" r="14"/><line x1="321" y1="81" x2="339" y2="99"/><line x1="339" y1="81" x2="321" y2="99"/><line x1="330" y1="104" x2="330" y2="155"/><text x="330" y="171" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A single bulb connected directly to a battery glows at a certain brightness. If a second identical bulb is added in series with the first, so both bulbs share the same single loop and the same current, what happens to the brightness of each bulb compared to the single-bulb case?',
 '["Each bulb glows brighter than the original single bulb", "Each bulb glows at the same brightness as the original single bulb", "Each bulb glows dimmer than the original single bulb", "The first bulb glows normally, but the second bulb does not light at all", "Only one of the two bulbs will glow at a time", "The brightness cannot be determined without knowing the wire length"]'::jsonb,
 2, 'Adding a second bulb in series increases the total resistance the battery has to push current through, which reduces the current flowing in the shared loop. With less current, each bulb glows more dimly than the original single bulb did.',
 '<svg viewBox="0 0 300 145" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="116" y2="30"/><circle cx="130" cy="30" r="14"/><line x1="121" y1="21" x2="139" y2="39"/><line x1="139" y1="21" x2="121" y2="39"/><text x="130" y="10" font-size="10.5" text-anchor="middle">Bulb 1</text><line x1="144" y1="30" x2="196" y2="30"/><circle cx="210" cy="30" r="14"/><line x1="201" y1="21" x2="219" y2="39"/><line x1="219" y1="21" x2="201" y2="39"/><text x="210" y="10" font-size="10.5" text-anchor="middle">Bulb 2</text><line x1="224" y1="30" x2="270" y2="30"/><line x1="270" y1="30" x2="270" y2="110"/><line x1="30" y1="110" x2="270" y2="110"/><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A single bulb connected directly to a battery glows at a certain brightness. If a second identical bulb is instead added in parallel with the first -- each bulb wired directly across the same battery terminals through separate wires -- what happens to the brightness of each bulb, assuming the battery can supply enough current?',
 '["Each bulb glows brighter than before", "Each bulb glows at about the same brightness as the original single bulb", "Each bulb glows dimmer than before", "Only one bulb will glow", "Both bulbs will flicker on and off", "The bulbs must be different sizes to both glow"]'::jsonb,
 1, 'In a parallel connection, each bulb is wired directly across the full battery voltage, independent of the other bulb. Since neither bulb''s own path changed, each glows at about the same brightness as it would alone.',
 '<svg viewBox="0 0 300 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="60"/><line x1="90" y1="25" x2="90" y2="120"/><line x1="90" y1="60" x2="166" y2="60"/><circle cx="180" cy="60" r="14"/><line x1="171" y1="51" x2="189" y2="69"/><line x1="189" y1="51" x2="171" y2="69"/><text x="180" y="40" font-size="10.5" text-anchor="middle">Bulb A</text><line x1="194" y1="60" x2="270" y2="60"/><line x1="90" y1="120" x2="166" y2="120"/><circle cx="180" cy="120" r="14"/><line x1="171" y1="111" x2="189" y2="129"/><line x1="189" y1="111" x2="171" y2="129"/><text x="180" y="148" font-size="10.5" text-anchor="middle">Bulb B</text><line x1="194" y1="120" x2="270" y2="120"/><line x1="270" y1="60" x2="270" y2="25"/><line x1="270" y1="120" x2="270" y2="25"/><line x1="270" y1="25" x2="270" y2="155"/><line x1="30" y1="155" x2="270" y2="155"/><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A security system''s siren is wired to a battery through two switches -- a Door Switch and a Window Switch -- connected in series, so the siren sounds only when current flows through both switches. Which combination of switch positions will cause the siren to sound?',
 '["Door Switch open, Window Switch open", "Door Switch closed, Window Switch open", "Door Switch open, Window Switch closed", "Door Switch closed, Window Switch closed", "Any single switch closed is enough", "The siren sounds only when both switches are open"]'::jsonb,
 3, 'Because the two switches are in series, they form a single shared path -- both must be closed for current to complete the loop. Leaving either switch open breaks the only path available, so the siren stays silent.',
 '<svg viewBox="0 0 300 145" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="30" x2="30" y2="62"/><line x1="19" y1="62" x2="41" y2="62" stroke-width="2"/><line x1="24" y1="72" x2="36" y2="72" stroke-width="6"/><line x1="30" y1="72" x2="30" y2="110"/><line x1="30" y1="30" x2="96" y2="30"/><circle cx="96" cy="30" r="2.5" fill="currentColor"/><line x1="96" y1="30" x2="121" y2="19"/><circle cx="124" cy="30" r="2.5" fill="currentColor"/><text x="110" y="18" font-size="10.5" text-anchor="middle">Door Switch</text><line x1="124" y1="30" x2="176" y2="30"/><circle cx="176" cy="30" r="2.5" fill="currentColor"/><line x1="176" y1="30" x2="201" y2="19"/><circle cx="204" cy="30" r="2.5" fill="currentColor"/><text x="190" y="18" font-size="10.5" text-anchor="middle">Window Switch</text><line x1="204" y1="30" x2="270" y2="30"/><line x1="30" y1="110" x2="270" y2="110"/><line x1="270" y1="30" x2="270" y2="56"/><circle cx="270" cy="70" r="14"/><line x1="261" y1="61" x2="279" y2="79"/><line x1="279" y1="61" x2="261" y2="79"/><line x1="270" y1="84" x2="270" y2="110"/><text x="270" y="126" font-size="11" text-anchor="middle">Siren</text><text x="30" y="126" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A doorbell is wired to a battery through two buttons, a Front Button and a Back Button, wired in parallel -- pressing either one closes that button''s own branch of the circuit. Which of the following will make the doorbell ring?',
 '["Front Button not pressed, Back Button not pressed", "Front Button pressed, Back Button not pressed", "Front Button not pressed, Back Button pressed", "Front Button pressed, Back Button pressed", "All of the above except the first option", "None of the above"]'::jsonb,
 4, 'Since the two buttons form separate parallel branches, pressing either one alone completes a path back to the battery. The doorbell only fails to ring when neither button is pressed.',
 '<svg viewBox="0 0 300 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="60"/><line x1="90" y1="25" x2="90" y2="120"/><line x1="90" y1="60" x2="136" y2="60"/><circle cx="136" cy="60" r="2.5" fill="currentColor"/><line x1="136" y1="60" x2="161" y2="49"/><circle cx="164" cy="60" r="2.5" fill="currentColor"/><text x="150" y="48" font-size="10.5" text-anchor="middle">Front Button</text><line x1="164" y1="60" x2="210" y2="60"/><line x1="90" y1="120" x2="136" y2="120"/><circle cx="136" cy="120" r="2.5" fill="currentColor"/><line x1="136" y1="120" x2="161" y2="109"/><circle cx="164" cy="120" r="2.5" fill="currentColor"/><text x="150" y="140" font-size="10.5" text-anchor="middle">Back Button</text><line x1="164" y1="120" x2="210" y2="120"/><line x1="210" y1="60" x2="210" y2="25"/><line x1="210" y1="120" x2="210" y2="25"/><line x1="210" y1="25" x2="270" y2="25"/><line x1="30" y1="155" x2="270" y2="155"/><line x1="270" y1="25" x2="270" y2="76"/><circle cx="270" cy="90" r="14"/><line x1="261" y1="81" x2="279" y2="99"/><line x1="279" y1="81" x2="261" y2="99"/><line x1="270" y1="104" x2="270" y2="155"/><text x="270" y="171" font-size="11" text-anchor="middle">Doorbell</text><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A circuit has two separate branches connecting the same battery and light bulb. Branch 1 contains Switch A and Switch B in series. Branch 2 contains Switch C and Switch D in series. The two branches are wired in parallel with each other. Which of the following will make the light glow?',
 '["Switch A closed, Switch B open, Switch C closed, Switch D open", "Switch A closed, Switch B closed, Switch C open, Switch D open", "Switch A open, Switch B open, Switch C closed, Switch D closed", "Both the second and third options above will make the light glow", "Switch A closed, Switch C closed, with Switch B and Switch D both open", "None of the above"]'::jsonb,
 3, 'Each branch needs both of its own switches closed to be complete, since the switches within a branch are in series. Closing A and B completes Branch 1; closing C and D completes Branch 2. Either branch being complete is enough, since the branches are in parallel.',
 '<svg viewBox="0 0 360 190" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="82"/><line x1="19" y1="82" x2="41" y2="82" stroke-width="2"/><line x1="24" y1="92" x2="36" y2="92" stroke-width="6"/><line x1="30" y1="92" x2="30" y2="155"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="55"/><line x1="90" y1="25" x2="90" y2="125"/><line x1="90" y1="55" x2="141" y2="55"/><circle cx="141" cy="55" r="2.5" fill="currentColor"/><line x1="141" y1="55" x2="166" y2="44"/><circle cx="169" cy="55" r="2.5" fill="currentColor"/><text x="155" y="43" font-size="10.5" text-anchor="middle">Switch A</text><line x1="169" y1="55" x2="201" y2="55"/><circle cx="201" cy="55" r="2.5" fill="currentColor"/><line x1="201" y1="55" x2="226" y2="44"/><circle cx="229" cy="55" r="2.5" fill="currentColor"/><text x="215" y="43" font-size="10.5" text-anchor="middle">Switch B</text><line x1="229" y1="55" x2="270" y2="55"/><line x1="90" y1="125" x2="141" y2="125"/><circle cx="141" cy="125" r="2.5" fill="currentColor"/><line x1="141" y1="125" x2="166" y2="114"/><circle cx="169" cy="125" r="2.5" fill="currentColor"/><text x="155" y="145" font-size="10.5" text-anchor="middle">Switch C</text><line x1="169" y1="125" x2="201" y2="125"/><circle cx="201" cy="125" r="2.5" fill="currentColor"/><line x1="201" y1="125" x2="226" y2="114"/><circle cx="229" cy="125" r="2.5" fill="currentColor"/><text x="215" y="145" font-size="10.5" text-anchor="middle">Switch D</text><line x1="229" y1="125" x2="270" y2="125"/><line x1="270" y1="55" x2="270" y2="25"/><line x1="270" y1="125" x2="270" y2="25"/><line x1="270" y1="25" x2="330" y2="25"/><line x1="30" y1="155" x2="330" y2="155"/><line x1="330" y1="25" x2="330" y2="76"/><circle cx="330" cy="90" r="14"/><line x1="321" y1="81" x2="339" y2="99"/><line x1="339" y1="81" x2="321" y2="99"/><line x1="330" y1="104" x2="330" y2="155"/><text x="330" y="171" font-size="11" text-anchor="middle">Bulb</text><text x="30" y="171" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A circuit has one switch, Switch 1, wired in series with Bulb A only. A completely separate branch has Bulb B wired directly to the battery with no switch at all. The two branches are otherwise independent of each other. What happens when Switch 1 is opened?',
 '["Both Bulb A and Bulb B turn off", "Bulb A turns off, but Bulb B keeps glowing", "Bulb B turns off, but Bulb A keeps glowing", "Both bulbs stay lit regardless of Switch 1", "Both bulbs turn off only if Switch 1 is closed", "Neither bulb will glow under any switch position"]'::jsonb,
 1, 'Switch 1 only controls Bulb A''s branch. Bulb B''s branch has no switch and is wired independently straight to the battery, so opening Switch 1 has no effect on it -- only Bulb A goes out.',
 '<svg viewBox="0 0 340 200" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="25" x2="30" y2="92"/><line x1="19" y1="92" x2="41" y2="92" stroke-width="2"/><line x1="24" y1="102" x2="36" y2="102" stroke-width="6"/><line x1="30" y1="102" x2="30" y2="175"/><line x1="30" y1="25" x2="90" y2="25"/><line x1="90" y1="25" x2="90" y2="60"/><line x1="90" y1="25" x2="90" y2="140"/><line x1="90" y1="60" x2="156" y2="60"/><circle cx="156" cy="60" r="2.5" fill="currentColor"/><line x1="156" y1="60" x2="181" y2="49"/><circle cx="184" cy="60" r="2.5" fill="currentColor"/><text x="170" y="48" font-size="10.5" text-anchor="middle">Switch 1</text><line x1="184" y1="60" x2="226" y2="60"/><circle cx="240" cy="60" r="14"/><line x1="231" y1="51" x2="249" y2="69"/><line x1="249" y1="51" x2="231" y2="69"/><text x="240" y="40" font-size="10.5" text-anchor="middle">Bulb A</text><line x1="254" y1="60" x2="300" y2="60"/><line x1="90" y1="140" x2="181" y2="140"/><circle cx="195" cy="140" r="14"/><line x1="186" y1="131" x2="204" y2="149"/><line x1="204" y1="131" x2="186" y2="149"/><text x="195" y="168" font-size="10.5" text-anchor="middle">Bulb B</text><line x1="209" y1="140" x2="300" y2="140"/><line x1="300" y1="60" x2="300" y2="25"/><line x1="300" y1="140" x2="300" y2="25"/><line x1="300" y1="25" x2="300" y2="175"/><line x1="30" y1="175" x2="300" y2="175"/><text x="30" y="191" font-size="11" text-anchor="middle">Battery</text></svg>'),

('acl', 'Logic/Reasoning', 'A circuit has a battery and a light bulb connected by a wire, forming a complete loop. A Switch X is added, but it is wired as a dead-end branch -- one end attached to the main wire, the other end not connected to anything else. If the main wire is intact and unbroken, will the light glow, and does Switch X''s position matter?',
 '["The light will not glow no matter what, since Switch X is broken", "The light will glow, and it depends on Switch X being closed", "The light will glow regardless of Switch X''s position, since the main loop is already complete", "The light will only glow if Switch X is closed and the main wire is also connected", "The light will flicker depending on Switch X''s position", "Not enough information is given to determine the answer"]'::jsonb,
 2, 'Current only flows through paths that form a complete loop back to the battery. Switch X dead-ends and isn''t part of any closed path, so it carries no current either way -- the light''s behavior depends entirely on the intact main loop, not on Switch X.',
 '<svg viewBox="0 0 320 165" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="30" y1="60" x2="30" y2="92"/><line x1="19" y1="92" x2="41" y2="92" stroke-width="2"/><line x1="24" y1="102" x2="36" y2="102" stroke-width="6"/><line x1="30" y1="102" x2="30" y2="140"/><line x1="30" y1="60" x2="270" y2="60"/><line x1="30" y1="140" x2="270" y2="140"/><line x1="270" y1="60" x2="270" y2="86"/><circle cx="270" cy="100" r="14"/><line x1="261" y1="91" x2="279" y2="109"/><line x1="279" y1="91" x2="261" y2="109"/><line x1="270" y1="114" x2="270" y2="140"/><text x="270" y="156" font-size="11" text-anchor="middle">Bulb</text><line x1="150" y1="60" x2="150" y2="38"/><circle cx="150" cy="38" r="2.5" fill="currentColor"/><line x1="150" y1="38" x2="161" y2="27"/><circle cx="150" cy="20" r="4"/><text x="188" y="24" font-size="10.5" text-anchor="middle">Switch X — dangling end</text><text x="30" y="156" font-size="11" text-anchor="middle">Battery</text></svg>');
